    // Keep the original synchronous preference API backed by IndexedDB.
    const preferenceKeys = [
      "iosLowSaturationDesktopLayoutV2", "iosDesktopAppNamesV1",
      "iosDesktopCustomHtmlAppsV1",
      "iosDesktopRemovedBuiltinAppsV1"
    ];
    const preferenceValues = new Map();
    await Promise.all(preferenceKeys.map(async key => {
      let value = await idbGet(`preference:${key}`);
      if (value === undefined) {
        value = window.localStorage.getItem(key);
        if (value !== null) await idbSet(`preference:${key}`, value);
      }
      if (value != null) preferenceValues.set(key, value);
    }));
    let preferenceWrites = Promise.resolve();
    const localStorage = {
      getItem(key) { return preferenceValues.get(key) ?? null; },
      setItem(key, value) {
        preferenceValues.set(key, String(value));
        preferenceWrites = preferenceWrites.catch(() => {}).then(() => idbSet(`preference:${key}`, String(value)));
        preferenceWrites.catch(error => console.error('Character phone preference save failed', error));
      },
      removeItem(key) {
        preferenceValues.delete(key);
        preferenceWrites = preferenceWrites.catch(() => {}).then(() => idbSet(`preference:${key}`, null));
        preferenceWrites.catch(error => console.error('Character phone preference save failed', error));
      }
    };

