    function updateClock() {
      const now = new Date();
      statusTime.textContent =
        `${now.getHours()}:${String(now.getMinutes()).padStart(2, "0")}`;
    }

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add("show");
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => toast.classList.remove("show"), 820);
    }

    function isEditing() {
      return document.body.classList.contains("editing");
    }

    function enterEditMode() {
      if (isEditing()) return;
      ensureEditDeleteButtons();
      document.body.classList.add("editing");
      updateDockVisual();
      showToast("编辑主屏幕");
    }

    function exitEditMode() {
      if (!isEditing()) return;

      if (dragState) {
        finishDrag(null, true);
      }

      document.body.classList.remove("editing");
      clearDropTarget();
      normalizeDock();
      updateDockVisual();
      saveLayout();
    }

    function createEmptyPage(index) {
      const page = document.createElement("section");
      page.className = "home-page";
      page.dataset.page = String(index);

      for (let i = 0; i < SLOT_COUNT; i += 1) {
        const slot = document.createElement("div");
        slot.className = "slot";
        slot.dataset.slot = String(i);
        page.appendChild(slot);
      }

      pagesTrack.appendChild(page);
      return page;
    }

    function updatePageMetadata() {
      [...pagesTrack.querySelectorAll(".home-page")].forEach((page, index) => {
        page.dataset.page = String(index);
      });
    }

    function renderDots() {
      const count = pagesTrack.querySelectorAll(".home-page").length;
      pageDots.innerHTML = "";

      for (let i = 0; i < count; i += 1) {
        const dot = document.createElement("button");
        dot.type = "button";
        dot.className = "page-dot" + (i === currentPage ? " active" : "");
        dot.dataset.pageIndex = String(i);
        dot.setAttribute("aria-label", `第 ${i + 1} 页`);
        pageDots.appendChild(dot);
      }
    }

    function goToPage(index) {
      const count = pagesTrack.querySelectorAll(".home-page").length;
      currentPage = Math.max(0, Math.min(index, count - 1));
      pagesTrack.style.transform = `translate3d(-${currentPage * 100}%, 0, 0)`;
      renderDots();

      if (dragState) {
        requestAnimationFrame(rebuildDropCache);
      }
    }

    function addPage() {
      if (!isEditing()) return;

      const nextIndex = pagesTrack.querySelectorAll(".home-page").length;
      createEmptyPage(nextIndex);
      updatePageMetadata();
      goToPage(nextIndex);
      saveLayout();
      showToast(`已新增第 ${nextIndex + 1} 页`);
    }

    function removeCurrentPage() {
      if (!isEditing() || dragState) return;

      const pages = [...pagesTrack.querySelectorAll(".home-page")];

      if (pages.length <= 1) {
        showToast("至少保留一个页面");
        return;
      }

      const page = pages[currentPage];
      const appsToMove = [...page.querySelectorAll(".slot > .app")];

      const freeSlots = pages
        .filter((item) => item !== page)
        .flatMap((item) =>
          [...item.querySelectorAll(".slot")].filter(
            (slot) => !slot.querySelector(":scope > .app")
          )
        );

      if (freeSlots.length < appsToMove.length) {
        showToast("其他页面没有足够空位");
        return;
      }

      appsToMove.forEach((app, index) => {
        freeSlots[index].appendChild(app);
      });

      page.remove();
      updatePageMetadata();

      const newCount = pagesTrack.querySelectorAll(".home-page").length;
      currentPage = Math.min(currentPage, newCount - 1);
      goToPage(currentPage);

      saveLayout();
      showToast("已删除当前页面");
    }

    function getAppId(app) {
      return app?.dataset?.name || "";
    }

    function getRemovedBuiltinApps() {
      try {
        const parsed = JSON.parse(localStorage.getItem(REMOVED_BUILTIN_APPS_KEY) || "[]");
        return new Set(Array.isArray(parsed) ? parsed : []);
      } catch (_) {
        return new Set();
      }
    }

    function saveRemovedBuiltinApps(set) {
      localStorage.setItem(REMOVED_BUILTIN_APPS_KEY, JSON.stringify([...set]));
    }

    function captureBuiltinAppCatalog() {
      document.querySelectorAll(".app[data-name]").forEach((app) => {
        if (app.dataset.customAppId) return;
        const id = getAppId(app);
        if (!id || builtinAppCatalog.has(id)) return;

        const template = app.cloneNode(true);
        template.querySelectorAll(".app-delete-button").forEach((button) => button.remove());

        builtinAppCatalog.set(id, {
          id,
          template
        });
      });
    }

    function applyRemovedBuiltinApps() {
      const removed = getRemovedBuiltinApps();
      removed.forEach((id) => {
        document.querySelector(`.app[data-name="${CSS.escape(id)}"]`)?.remove();
      });
    }

    function ensureEditDeleteButtons() {
      document.querySelectorAll(".app:not(.drag-ghost)").forEach((app) => {
        if (app.querySelector(":scope > .app-delete-button")) return;

        const button = document.createElement("button");
        button.type = "button";
        button.className = "app-delete-button";
        button.setAttribute("aria-label", "删除 App");
        button.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16" aria-hidden="true"><path fill-rule="evenodd" d="M2 8a.5.5 0 0 1 .5-.5h11a.5.5 0 0 1 0 1h-11A.5.5 0 0 1 2 8"/></svg>`;
        app.appendChild(button);
      });
    }

    async function removeDesktopApp(app) {
      if (!app || app.dataset.name === "App Store") return;

      const id = getAppId(app);

      if (app.dataset.customAppId) {
        const apps = getCustomApps();
        const item = apps.find((entry) => entry.id === app.dataset.customAppId);
        if (item) {
          item.installed = false;
          try {
            await saveCustomApps(apps);
          } catch (error) {
            console.error("custom app uninstall persist failed", error);
          }
        }
      } else {
        const removed = getRemovedBuiltinApps();
        removed.add(id);
        saveRemovedBuiltinApps(removed);
      }

      app.remove();
      normalizeDock();
      updateDockVisual();
      saveLayout();
      renderDots();
      renderHomeSettings();
      showToast("已从桌面移除，可在 App Store 重新获取");
    }

    async function installBuiltinApp(id) {
      const catalogEntry = builtinAppCatalog.get(id);
      if (!catalogEntry) return null;

      let app = document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
      if (app) return app;

      let slot = findFirstEmptyDesktopSlot();

      if (!slot) {
        const page = createEmptyPage(pagesTrack.querySelectorAll(".home-page").length);
        pagesTrack.appendChild(page);
        slot = page.querySelector(".slot");
        updatePageMetadata();
        renderDots();
      }

      app = catalogEntry.template.cloneNode(true);
      slot.appendChild(app);

      const removed = getRemovedBuiltinApps();
      removed.delete(id);
      saveRemovedBuiltinApps(removed);

      const savedNames = getSavedAppNames();
      const label = app.querySelector(".app-label");
      if (label && savedNames[id]) label.textContent = savedNames[id];

      captureAppDefaults();
      await applyStoredAppIcon(id).catch(() => {});
      ensureEditDeleteButtons();
      saveLayout();
      updateDockVisual();
      return app;
    }

    function getDockSlots() {
      return [...dock.querySelectorAll(".dock-slot")];
    }

    function getDockApps() {
      return getDockSlots()
        .map((slot) => slot.querySelector(":scope > .app"))
        .filter(Boolean);
    }

    function normalizeDock() {
      const slots = getDockSlots();
      const apps = getDockApps();

      apps.slice(0, DOCK_CAPACITY).forEach((app, index) => {
        slots[index].appendChild(app);
      });
    }

    function updateDockVisual() {
      const count = getDockApps().length;
      dockWrap.classList.toggle("dock-empty", count === 0);

      if (isEditing()) {
        dock.style.gridTemplateColumns = `repeat(${DOCK_CAPACITY}, 1fr)`;
        dock.style.width = "min(316px, 100%)";
      } else {
        const visibleCount = Math.max(1, count);
        dock.style.gridTemplateColumns = `repeat(${visibleCount}, 1fr)`;
        dock.style.width = `${Math.min(316, visibleCount * 72 + 28)}px`;
      }
    }


    function openPersonalizationDB() {
      return new Promise((resolve, reject) => {
        const request = indexedDB.open(PERSONALIZATION_DB_NAME, 1);

        request.onupgradeneeded = () => {
          const db = request.result;
          if (!db.objectStoreNames.contains(PERSONALIZATION_STORE)) {
            db.createObjectStore(PERSONALIZATION_STORE);
          }
        };

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    }

    async function idbGet(key) {
      const db = await openPersonalizationDB();

      return new Promise((resolve, reject) => {
        const tx = db.transaction(PERSONALIZATION_STORE, "readonly");
        const request = tx.objectStore(PERSONALIZATION_STORE).get(key);

        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
        tx.oncomplete = () => db.close();
      });
    }

    async function idbSet(key, value) {
      const db = await openPersonalizationDB();

      return new Promise((resolve, reject) => {
        const tx = db.transaction(PERSONALIZATION_STORE, "readwrite");
        tx.objectStore(PERSONALIZATION_STORE).put(value, key);

        tx.oncomplete = () => {
          db.close();
          resolve();
        };
        tx.onerror = () => {
          db.close();
          reject(tx.error);
        };
      });
    }

    async function idbDelete(key) {
      const db = await openPersonalizationDB();

      return new Promise((resolve, reject) => {
        const tx = db.transaction(PERSONALIZATION_STORE, "readwrite");
        tx.objectStore(PERSONALIZATION_STORE).delete(key);

        tx.oncomplete = () => {
          db.close();
          resolve();
        };
        tx.onerror = () => {
          db.close();
          reject(tx.error);
        };
      });
    }

    function captureAppDefaults() {
      document.querySelectorAll(".app[data-name]").forEach((app) => {
        const id = app.dataset.name;
        const label = app.querySelector(".app-label");
        const icon = app.querySelector(".app-icon");

        if (!appDefaults.has(id)) {
          appDefaults.set(id, {
            name: label?.textContent || id,
            iconHTML: icon?.innerHTML || ""
          });
        }
      });
    }

    function getSavedAppNames() {
      try {
        return JSON.parse(localStorage.getItem(APP_NAME_STORAGE_KEY) || "{}");
      } catch (_) {
        return {};
      }
    }

    function saveAppNames(names) {
      localStorage.setItem(APP_NAME_STORAGE_KEY, JSON.stringify(names));
    }

    function getAppDisplayName(app) {
      return app?.querySelector(".app-label")?.textContent || app?.dataset?.name || "";
    }

    function setAppDisplayName(id, name) {
      const app = document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
      if (!app) return;

      const defaults = appDefaults.get(id);
      const cleanName = name.trim() || defaults?.name || id;
      const label = app.querySelector(".app-label");

      if (label) {
        label.textContent = cleanName;
      }

      const names = getSavedAppNames();

      if (defaults && cleanName === defaults.name) {
        delete names[id];
      } else {
        names[id] = cleanName;
      }

      saveAppNames(names);
      renderHomeSettings();
    }

    function revokeAppIconUrl(id) {
      const oldUrl = customIconObjectUrls.get(id);
      if (oldUrl) {
        URL.revokeObjectURL(oldUrl);
        customIconObjectUrls.delete(id);
      }
    }

    function readBlobAsDataURL(blob) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(reader.error || new Error("读取图片失败"));
        reader.readAsDataURL(blob);
      });
    }

    function validateImageDataURL(dataUrl) {
      return new Promise((resolve, reject) => {
        const image = new Image();

        image.onload = () => resolve();
        image.onerror = () => reject(new Error("图片无法显示"));
        image.src = dataUrl;
      });
    }

    function applyCustomIconDataToApp(id, dataUrl) {
      const app = document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
      const icon = app?.querySelector(".app-icon");

      if (!icon || !dataUrl) return false;

      revokeAppIconUrl(id);

      const image = document.createElement("img");
      image.src = dataUrl;
      image.alt = "";
      image.decoding = "async";
      image.draggable = false;

      icon.classList.add("custom-user-icon");
      icon.replaceChildren(image);
      return true;
    }

    async function applyStoredAppIcon(id) {
      const stored = await idbGet(`app-icon:${id}`);
      if (!stored) return;

      if (stored.kind === "data-url" && typeof stored.data === "string") {
        applyCustomIconDataToApp(id, stored.data);
        return;
      }

      // Migrate older Blob entries so local/content:// pages no longer depend on Blob URLs.
      if (stored.kind === "blob" && stored.data instanceof Blob) {
        const dataUrl = await readBlobAsDataURL(stored.data);
        await validateImageDataURL(dataUrl);
        applyCustomIconDataToApp(id, dataUrl);
        await idbSet(`app-icon:${id}`, {
          kind: "data-url",
          data: dataUrl
        });
        return;
      }

      // Migrate the older inline SVG format too.
      if (stored.kind === "svg" && typeof stored.data === "string") {
        const blob = new Blob([stored.data], { type: "image/svg+xml" });
        const dataUrl = await readBlobAsDataURL(blob);
        await validateImageDataURL(dataUrl);
        applyCustomIconDataToApp(id, dataUrl);
        await idbSet(`app-icon:${id}`, {
          kind: "data-url",
          data: dataUrl
        });
      }
    }

    async function setCustomAppIcon(id, file) {
      if (!file) return;

      const validImage =
        file.type.startsWith("image/") ||
        file.name.toLowerCase().endsWith(".svg");

      if (!validImage) {
        showToast("请选择图片或 SVG");
        return;
      }

      try {
        const dataUrl = await readBlobAsDataURL(file);
        await validateImageDataURL(dataUrl);

        if (!applyCustomIconDataToApp(id, dataUrl)) {
          showToast("没有找到对应的桌面 App");
          return;
        }

        await idbSet(`app-icon:${id}`, {
          kind: "data-url",
          data: dataUrl
        });

        selectedHomeAppId = id;
        renderHomeSettings();
        showToast("桌面图标已更新");
      } catch (_) {
        showToast("图片读取失败，请换一张图片");
      }
    }


    async function resetAppIcon(id) {
      const app = document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
      const icon = app?.querySelector(".app-icon");
      const defaults = appDefaults.get(id);
      if (!icon || !defaults) return;

      revokeAppIconUrl(id);
      icon.classList.remove("custom-user-icon");
      icon.innerHTML = defaults.iconHTML;
      await idbDelete(`app-icon:${id}`);
      renderHomeSettings();
    }

    async function loadSavedAppCustomizations() {
      const names = getSavedAppNames();

      document.querySelectorAll(".app[data-name]").forEach((app) => {
        const id = app.dataset.name;
        const label = app.querySelector(".app-label");

        if (label && names[id]) {
          label.textContent = names[id];
        }
      });

      await Promise.all(
        [...appDefaults.keys()].map((id) => applyStoredAppIcon(id).catch(() => {}))
      );
    }

    function getAppsInVisualOrder() {
      const pages = [...pagesTrack.querySelectorAll(".home-page")];
      const pageApps = pages.flatMap((page) =>
        [...page.querySelectorAll(".slot > .app")]
      );
      const dockApps = getDockApps();
      const seen = new Set();

      return [...pageApps, ...dockApps].filter((app) => {
        const id = app.dataset.name;
        if (!id || seen.has(id)) return false;
        seen.add(id);
        return true;
      });
    }

    function cloneAppIcon(app, extraClass = "") {
      const icon = app.querySelector(".app-icon");
      if (!icon) return document.createElement("span");

      const clone = icon.cloneNode(true);
      if (extraClass) {
        clone.classList.add(extraClass);
      }

      return clone;
    }

    function getHomeAppById(id) {
      return document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
    }

    function selectHomeApp(id) {
      if (!getHomeAppById(id)) return;
      selectedHomeAppId = id;
      renderHomeSettings();
    }

    function renderHomeEditor(app) {
      if (!app) {
        homeEditorTitle.textContent = "—";
        homeEditorNameInput.value = "";
        homeEditorIconButton.innerHTML = "";
        return;
      }

      const id = app.dataset.name;
      const displayName = getAppDisplayName(app);

      homeEditorTitle.textContent = displayName;
      homeEditorNameInput.value = displayName;
      homeEditorLabelColorInput.value = readLabelColors()[id] || "#333333";
      homeEditorIconButton.innerHTML = "";
      homeEditorIconButton.appendChild(cloneAppIcon(app));
      homeEditorIconButton.setAttribute("aria-label", `更换 ${displayName} 图标`);
    }

    function renderHomeSettings() {
      if (!homePreviewGrid) return;

      const apps = getAppsInVisualOrder();
      if (!apps.length) return;

      if (
        !selectedHomeAppId ||
        !apps.some((app) => app.dataset.name === selectedHomeAppId)
      ) {
        selectedHomeAppId = apps[0].dataset.name;
      }

      homePreviewGrid.innerHTML = "";

      apps.forEach((app) => {
        const id = app.dataset.name;
        const displayName = getAppDisplayName(app);

        const previewButton = document.createElement("button");
        previewButton.type = "button";
        previewButton.className =
          "home-preview-app" +
          (id === selectedHomeAppId ? " selected" : "");
        previewButton.style.appearance = "none";
        previewButton.style.border = "0";
        previewButton.style.background = "transparent";
        previewButton.setAttribute("aria-label", `自定义 ${displayName}`);
        previewButton.appendChild(cloneAppIcon(app));

        const previewName = document.createElement("div");
        previewName.className = "home-preview-name";
        previewName.textContent = displayName;
        previewButton.appendChild(previewName);

        previewButton.addEventListener("click", () => {
          selectedHomeAppId = id;
          renderHomeSettings();
        });

        homePreviewGrid.appendChild(previewButton);
      });

      renderHomeEditor(getHomeAppById(selectedHomeAppId));

      const currentWallpaper = getWallpaperEntries().find(
        (entry) => entry.id === activeWallpaperId
      );
      applyWallpaperEntry(currentWallpaper || getWallpaperEntries()[0]);
    }

    function openSubpage(page) {
      page.classList.add("open");
      page.setAttribute("aria-hidden", "false");
      page.scrollTop = 0;
    }

    function closeSubpage(page) {
      if (page === homeScreenSettings) root.style.zIndex = "10000";
      page.classList.remove("open");
      page.setAttribute("aria-hidden", "true");
    }

    function openWallpaperPage() {
      renderWallpaperCarousel();
      openSubpage(wallpaperScreen);

      requestAnimationFrame(() => {
        scrollWallpaperToIndex(
          Math.max(
            0,
            getWallpaperEntries().findIndex((entry) => entry.id === activeWallpaperId)
          ),
          false
        );
      });
    }

    function openHomeScreenPage() {
      renderHomeSettings();
      openSubpage(homeScreenSettings);
    }

    function getWallpaperEntries() {
      return [
        {
          id: "default",
          name: "纯白",
          blob: null
        },
        ...wallpaperLibrary
      ];
    }

    function clearWallpaperPreviewUrls() {
      wallpaperPreviewUrls.forEach((url) => URL.revokeObjectURL(url));
      wallpaperPreviewUrls.clear();
    }

    function getWallpaperEntryUrl(entry) {
      if (!entry || !entry.blob) return null;

      if (!wallpaperPreviewUrls.has(entry.id)) {
        wallpaperPreviewUrls.set(entry.id, URL.createObjectURL(entry.blob));
      }

      return wallpaperPreviewUrls.get(entry.id);
    }

    function applyWallpaperEntry(entry) {
      const phone = document.querySelector(".phone");
      const url = getWallpaperEntryUrl(entry);

      activeWallpaperId = entry?.id || "default";

      if (url) {
        phone.style.backgroundImage = `url("${url}")`;
        phone.style.backgroundColor = "#ffffff";
        phone.style.backgroundSize = "cover";
        phone.style.backgroundPosition = "center";
        phone.style.backgroundRepeat = "no-repeat";
      } else {
        phone.style.removeProperty("background-image");
        phone.style.backgroundColor = "#ffffff";
        phone.style.removeProperty("background-size");
        phone.style.removeProperty("background-position");
        phone.style.removeProperty("background-repeat");
      }

      if (homeLayoutPreview) {
        if (url) {
          homeLayoutPreview.style.backgroundImage = `url("${url}")`;
          homeLayoutPreview.style.backgroundColor = "#ffffff";
          homeLayoutPreview.style.backgroundSize = "cover";
          homeLayoutPreview.style.backgroundPosition = "center";
          homeLayoutPreview.style.backgroundRepeat = "no-repeat";
        } else {
          homeLayoutPreview.style.removeProperty("background-image");
          homeLayoutPreview.style.backgroundColor = "#ffffff";
          homeLayoutPreview.style.removeProperty("background-size");
          homeLayoutPreview.style.removeProperty("background-position");
          homeLayoutPreview.style.removeProperty("background-repeat");
        }
      }
    }

    async function setActiveWallpaper(id, { persist = true, rerender = true } = {}) {
      const entries = getWallpaperEntries();
      const entry = entries.find((item) => item.id === id) || entries[0];

      applyWallpaperEntry(entry);

      if (persist) {
        await idbSet("active-wallpaper-id", entry.id);
        if (entry.blob) {
          await idbSet("wallpaper", entry.blob);
        } else {
          await idbDelete("wallpaper").catch(() => {});
        }
      }

      if (rerender) {
        renderWallpaperCarousel();
      }
    }

    function createWallpaperDevice(url, type, active) {
      const device = document.createElement("div");
      device.className = "wallpaper-device";

      if (url) {
        device.style.backgroundImage = `url("${url}")`;
      }

      if (type === "lock") {
        const time = document.createElement("div");
        time.className = "wallpaper-lock-time";
        time.textContent = "09:41";
        device.appendChild(time);
      }

      const badge = document.createElement("div");
      badge.className = "wallpaper-device-label";
      badge.textContent = active ? "当前" : "设为当前";
      device.appendChild(badge);

      return device;
    }

    function renderWallpaperCarousel() {
      if (!wallpaperCarouselTrack || !wallpaperCarouselDots) return;

      const entries = getWallpaperEntries();
      const previousVisibleId = entries[visibleWallpaperIndex]?.id || activeWallpaperId;

      wallpaperCarouselTrack.innerHTML = "";
      wallpaperCarouselDots.innerHTML = "";

      entries.forEach((entry, index) => {
        const url = getWallpaperEntryUrl(entry);
        const active = entry.id === activeWallpaperId;

        const slide = document.createElement("div");
        slide.className = "wallpaper-slide" + (active ? " is-active" : "");
        slide.dataset.wallpaperId = entry.id;
        slide.dataset.wallpaperIndex = String(index);

        const selectButton = document.createElement("button");
        selectButton.type = "button";
        selectButton.className = "wallpaper-slide-select";
        selectButton.setAttribute(
          "aria-label",
          active ? `${entry.name}，当前墙纸` : `设为墙纸：${entry.name}`
        );

        const pair = document.createElement("div");
        pair.className = "wallpaper-pair";
        pair.append(
          createWallpaperDevice(url, "lock", active),
          createWallpaperDevice(url, "home", active)
        );

        selectButton.appendChild(pair);
        selectButton.addEventListener("click", async () => {
          if (entry.id !== activeWallpaperId) {
            await setActiveWallpaper(entry.id);
            showToast("已设为当前墙纸");
          }
        });

        slide.appendChild(selectButton);
        wallpaperCarouselTrack.appendChild(slide);

        const dot = document.createElement("button");
        dot.type = "button";
        dot.className =
          "wallpaper-dot" +
          (index === visibleWallpaperIndex ? " visible" : "") +
          (active ? " current" : "");
        dot.setAttribute("aria-label", `查看第 ${index + 1} 组墙纸`);
        dot.addEventListener("click", () => scrollWallpaperToIndex(index));
        wallpaperCarouselDots.appendChild(dot);
      });

      const restoredIndex = Math.max(
        0,
        entries.findIndex((entry) => entry.id === previousVisibleId)
      );
      visibleWallpaperIndex = Math.min(restoredIndex, entries.length - 1);

      requestAnimationFrame(() => {
        scrollWallpaperToIndex(visibleWallpaperIndex, false);
      });
    }

    function scrollWallpaperToIndex(index, smooth = true) {
      const slides = [...wallpaperCarouselTrack.querySelectorAll(".wallpaper-slide")];
      const slide = slides[index];
      if (!slide) return;

      visibleWallpaperIndex = index;

      slide.scrollIntoView({
        behavior: smooth ? "smooth" : "auto",
        block: "nearest",
        inline: "center"
      });

      updateWallpaperDots();
    }

    function updateWallpaperDots() {
      [...wallpaperCarouselDots.children].forEach((dot, index) => {
        dot.classList.toggle("visible", index === visibleWallpaperIndex);
      });
    }

    function syncVisibleWallpaperIndexFromScroll() {
      const slides = [...wallpaperCarouselTrack.querySelectorAll(".wallpaper-slide")];
      if (!slides.length) return;

      const center = wallpaperCarousel.scrollLeft + wallpaperCarousel.clientWidth / 2;
      let nearestIndex = 0;
      let nearestDistance = Infinity;

      slides.forEach((slide, index) => {
        const slideCenter = slide.offsetLeft + slide.offsetWidth / 2;
        const distance = Math.abs(slideCenter - center);

        if (distance < nearestDistance) {
          nearestDistance = distance;
          nearestIndex = index;
        }
      });

      if (nearestIndex !== visibleWallpaperIndex) {
        visibleWallpaperIndex = nearestIndex;
        updateWallpaperDots();
      }
    }

    async function loadSavedWallpaper() {
      const savedLibrary = await idbGet("wallpaper-library");
      const legacyWallpaper = await idbGet("wallpaper");
      const savedActive = await idbGet("active-wallpaper-id");

      if (Array.isArray(savedLibrary)) {
        wallpaperLibrary = savedLibrary.filter(
          (entry) => entry && typeof entry.id === "string" && entry.blob instanceof Blob
        );
      } else if (legacyWallpaper instanceof Blob) {
        wallpaperLibrary = [{
          id: "legacy-wallpaper",
          name: "已保存墙纸",
          blob: legacyWallpaper
        }];
        await idbSet("wallpaper-library", wallpaperLibrary);
      }

      activeWallpaperId =
        typeof savedActive === "string"
          ? savedActive
          : (legacyWallpaper instanceof Blob ? "legacy-wallpaper" : "default");

      const entries = getWallpaperEntries();
      if (!entries.some((entry) => entry.id === activeWallpaperId)) {
        activeWallpaperId = "default";
      }

      clearWallpaperPreviewUrls();
      applyWallpaperEntry(
        entries.find((entry) => entry.id === activeWallpaperId) || entries[0]
      );
      renderWallpaperCarousel();
    }

    async function setWallpaperFile(file) {
      if (!file) return;

      const validImage =
        file.type.startsWith("image/") ||
        file.name.toLowerCase().endsWith(".svg");

      if (!validImage) {
        showToast("请选择图片");
        return;
      }

      const id =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? `wallpaper-${crypto.randomUUID()}`
          : `wallpaper-${Date.now()}`;

      wallpaperLibrary.push({
        id,
        name: file.name || "自定义墙纸",
        blob: file
      });

      await idbSet("wallpaper-library", wallpaperLibrary);

      clearWallpaperPreviewUrls();
      activeWallpaperId = id;

      // Apply to the real desktop immediately.
      const entry = getWallpaperEntries().find((item) => item.id === id);
      applyWallpaperEntry(entry);

      // Persist the selected wallpaper for reload.
      await idbSet("active-wallpaper-id", id);
      await idbSet("wallpaper", file);

      renderWallpaperCarousel();

      const newIndex = getWallpaperEntries().findIndex((item) => item.id === id);
      requestAnimationFrame(() => scrollWallpaperToIndex(newIndex, false));

      showToast("新墙纸已应用到桌面");
    }


    async function resetSingleHomeApp(id) {
      const app = getHomeAppById(id);
      const defaults = appDefaults.get(id);
      if (!app || !defaults) return;

      const label = app.querySelector(".app-label");
      const icon = app.querySelector(".app-icon");

      if (label) {
        label.textContent = defaults.name;
      }

      const colors = readLabelColors();
      delete colors[id];
      localStorage.setItem(savedLabelColorsKey, JSON.stringify(colors));
      if (label) label.style.removeProperty("color");
      const names = getSavedAppNames();
      delete names[id];
      saveAppNames(names);

      revokeAppIconUrl(id);

      if (icon) {
        icon.classList.remove("custom-user-icon");
        icon.innerHTML = defaults.iconHTML;
      }

      await idbDelete(`app-icon:${id}`).catch(() => {});
      selectedHomeAppId = id;
      renderHomeSettings();
      showToast("已恢复此 App");
    }

    async function resetAllHomeCustomizations() {
      localStorage.removeItem(savedLabelColorsKey);
      document.querySelectorAll(".app-label").forEach(label => label.style.removeProperty("color"));
      const names = {};

      saveAppNames(names);

      for (const [id, defaults] of appDefaults.entries()) {
        const app = document.querySelector(`.app[data-name="${CSS.escape(id)}"]`);
        if (!app) continue;

        const label = app.querySelector(".app-label");
        const icon = app.querySelector(".app-icon");

        if (label) label.textContent = defaults.name;

        revokeAppIconUrl(id);

        if (icon) {
          icon.classList.remove("custom-user-icon");
          icon.innerHTML = defaults.iconHTML;
        }

        await idbDelete(`app-icon:${id}`).catch(() => {});
      }

      renderHomeSettings();
      showToast("已恢复默认");
    }

    function openSettings() {
      if (isEditing()) return;
      // Keep the Apple account row attached to the selected character, never its remark.
      const accountName=settingsScreen.querySelector('.settings-account-title');
      if(accountName)accountName.textContent=roleEntry.contact?.name || '角色';
      setRoleAvatar(settingsScreen.querySelector('.settings-account-avatar'));
      document.body.classList.add("settings-open");
      settingsScreen.setAttribute("aria-hidden", "false");
      settingsScreen.scrollTop = 0;
      settingsSearchInput.value = "";
      filterSettings("");
    }

    function filterSettings(keyword) {
      const query = keyword.trim().toLowerCase();
      let visibleCount = 0;

      settingsScreen.querySelectorAll("[data-settings-group]").forEach((group) => {
        let groupVisible = 0;

        group.querySelectorAll("[data-setting-item]").forEach((row) => {
          const title = row.dataset.settingItem.toLowerCase();
          const visible = !query || title.includes(query);
          row.hidden = !visible;

          if (visible) {
            groupVisible += 1;
            visibleCount += 1;
          }
        });

        group.hidden = groupVisible === 0;
      });

      settingsEmptyState.classList.toggle("show", visibleCount === 0);
    }

    function closeSettings() {
      root.shadowRoot?.getElementById("charphoneLockSettings")?.classList.remove("open");
      closeSubpage(wallpaperScreen);
      closeSubpage(homeScreenSettings);
      closeAllInsightsPages();
      document.body.classList.remove("settings-open");
      settingsScreen.setAttribute("aria-hidden", "true");
    }

    function serializeLayout() {
      const pages = [...pagesTrack.querySelectorAll(".home-page")].map((page) =>
        [...page.querySelectorAll(".slot")].map((slot) => {
          const app = slot.querySelector(":scope > .app");
          return app ? getAppId(app) : null;
        })
      );

      const dockState = getDockSlots().map((slot) => {
        const app = slot.querySelector(":scope > .app");
        return app ? getAppId(app) : null;
      });

      return {
        pages,
        dock: dockState,
        currentPage
      };
    }

    function saveLayout() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(serializeLayout()));
      } catch (_) {}
    }

    function getAllAppsByName() {
      const map = new Map();

      document.querySelectorAll(".app[data-name]:not(.drag-ghost)").forEach((app) => {
        map.set(getAppId(app), app);
      });

      return map;
    }

    function restoreLayout() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) {
          normalizeDock();
          updateDockVisual();
          return;
        }

        const state = JSON.parse(raw);
        if (!Array.isArray(state.pages) || !Array.isArray(state.dock)) {
          normalizeDock();
          updateDockVisual();
          return;
        }

        const apps = getAllAppsByName();
        const knownNames = new Set(apps.keys());
        const savedNames = new Set(
          [...state.pages.flat(), ...state.dock].filter(Boolean)
        );

        if ([...knownNames].some((name) => name !== '论坛' && !savedNames.has(name))) {
          normalizeDock();
          updateDockVisual();
          return;
        }

        pagesTrack.innerHTML = "";

        state.pages.forEach((pageState, pageIndex) => {
          const page = createEmptyPage(pageIndex);
          const slots = [...page.querySelectorAll(".slot")];

          pageState.slice(0, SLOT_COUNT).forEach((name, slotIndex) => {
            if (name && apps.has(name)) {
              slots[slotIndex].appendChild(apps.get(name));
            }
          });
        });

        if (!pagesTrack.children.length) {
          createEmptyPage(0);
        }

        const dockSlots = getDockSlots();

        state.dock.slice(0, DOCK_CAPACITY).forEach((name, index) => {
          if (name && apps.has(name)) {
            dockSlots[index].appendChild(apps.get(name));
          }
        });

        const firstPage = pagesTrack.querySelector(".home-page");
        const fallbackSlots = [...firstPage.querySelectorAll(".slot")];

        apps.forEach((app) => {
          if (
            !app.parentElement?.classList.contains("slot") &&
            !app.parentElement?.classList.contains("dock-slot")
          ) {
            const emptySlot = fallbackSlots.find(
              (slot) => !slot.querySelector(":scope > .app")
            );

            if (emptySlot) {
              emptySlot.appendChild(app);
            } else if (getAppId(app) === '论坛') {
              const extraPage = createEmptyPage(pagesTrack.children.length);
              pagesTrack.appendChild(extraPage);
              extraPage.querySelector('.slot')?.appendChild(app);
            }
          }
        });

        normalizeDock();
        updatePageMetadata();
        currentPage = Number.isInteger(state.currentPage)
          ? state.currentPage
          : 0;
        goToPage(currentPage);
        updateDockVisual();
      } catch (_) {
        normalizeDock();
        updateDockVisual();
      }
    }

    function clearLongPress() {
      clearTimeout(longPressTimer);
      longPressTimer = null;
      pressState = null;
    }

    function setDropTarget(target) {
      if (activeDropTarget === target) return;

      if (activeDropTarget) {
        activeDropTarget.classList.remove("drop-target");
      }

      activeDropTarget = target || null;

      if (activeDropTarget) {
        activeDropTarget.classList.add("drop-target");
      }
    }

    function clearDropTarget() {
      setDropTarget(null);
    }

    function clearEdgeSwitch() {
      clearTimeout(edgeTimer);
      edgeTimer = null;
      edgeDirection = 0;
    }

    function rebuildDropCache() {
      if (!dragState) {
        dropCache = [];
        return;
      }

      const currentPageElement =
        pagesTrack.querySelector(`.home-page[data-page="${currentPage}"]`);
      const pageSlots = currentPageElement
        ? [...currentPageElement.querySelectorAll(".slot")]
        : [];

      const targets = [...pageSlots, ...getDockSlots()];

      dropCache = targets.map((element) => {
        const rect = element.getBoundingClientRect();

        return {
          element,
          left: rect.left,
          right: rect.right,
          top: rect.top,
          bottom: rect.bottom
        };
      });
    }

    function findCachedDropTarget(x, y) {
      for (let i = 0; i < dropCache.length; i += 1) {
        const item = dropCache[i];

        if (
          x >= item.left &&
          x <= item.right &&
          y >= item.top &&
          y <= item.bottom
        ) {
          return item.element;
        }
      }

      return null;
    }

    function maybeSwitchPageAtEdge(x) {
      if (!dragState) return;

      const viewportRect = pagesViewport.getBoundingClientRect();
      const threshold = 32;
      const pageCount = pagesTrack.querySelectorAll(".home-page").length;
      let direction = 0;

      if (x < viewportRect.left + threshold && currentPage > 0) {
        direction = -1;
      } else if (
        x > viewportRect.right - threshold &&
        currentPage < pageCount - 1
      ) {
        direction = 1;
      }

      if (!direction) {
        clearEdgeSwitch();
        return;
      }

      if (edgeTimer && edgeDirection === direction) return;

      clearEdgeSwitch();
      edgeDirection = direction;

      edgeTimer = setTimeout(() => {
        goToPage(currentPage + direction);
        clearDropTarget();
        clearEdgeSwitch();

        requestAnimationFrame(() => {
          rebuildDropCache();

          if (dragState) {
            setDropTarget(
              findCachedDropTarget(dragState.latestX, dragState.latestY)
            );
          }
        });
      }, EDGE_SWITCH_MS);
    }

    function startDrag(app, pointerLikeEvent) {
      if (!isEditing() || dragState) return;

      const originSlot = app.parentElement;
      const rect = app.getBoundingClientRect();

      const ghost = app.cloneNode(true);
      ghost.classList.add("drag-ghost");
      ghost.removeAttribute("id");
      ghost.setAttribute("aria-hidden", "true");
      ghost.style.width = `${rect.width}px`;
      ghost.style.height = `${rect.height}px`;

      document.body.appendChild(ghost);

      app.classList.add("drag-source");
      originSlot.classList.add("drag-origin");
      document.body.classList.add("dragging-active");

      dragState = {
        app,
        ghost,
        originSlot,
        pointerId: pointerLikeEvent.pointerId,
        startX: pointerLikeEvent.clientX,
        startY: pointerLikeEvent.clientY,
        latestX: pointerLikeEvent.clientX,
        latestY: pointerLikeEvent.clientY,
        startLeft: rect.left,
        startTop: rect.top,
        targetSlot: originSlot
      };

      try {
        app.setPointerCapture(pointerLikeEvent.pointerId);
      } catch (_) {}

      rebuildDropCache();
      queueDragFrame();
      suppressClickUntil = Date.now() + 650;
    }

    function renderDragFrame() {
      dragFrame = 0;
      if (!dragState) return;

      const {
        ghost,
        latestX,
        latestY,
        startX,
        startY,
        startLeft,
        startTop
      } = dragState;

      const x = startLeft + (latestX - startX);
      const y = startTop + (latestY - startY);

      ghost.style.transform =
        `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;

      const target = findCachedDropTarget(latestX, latestY);
      dragState.targetSlot = target;
      setDropTarget(target);
      maybeSwitchPageAtEdge(latestX);
    }

    function queueDragFrame() {
      if (dragFrame || !dragState) return;
      dragFrame = requestAnimationFrame(renderDragFrame);
    }

    function updateDrag(event) {
      if (!dragState || dragState.pointerId !== event.pointerId) return;

      dragState.latestX = event.clientX;
      dragState.latestY = event.clientY;
      queueDragFrame();
    }

    function finishDrag(event, cancel = false) {
      if (!dragState) return;

      if (dragFrame) {
        cancelAnimationFrame(dragFrame);
        dragFrame = 0;
      }

      clearEdgeSwitch();

      const {
        app,
        ghost,
        originSlot,
        pointerId
      } = dragState;

      const targetSlot = cancel
        ? originSlot
        : (dragState.targetSlot || originSlot);

      clearDropTarget();

      if (targetSlot !== originSlot) {
        const targetApp =
          targetSlot.querySelector(":scope > .app:not(.drag-ghost)");

        if (targetApp && targetApp !== app) {
          originSlot.appendChild(targetApp);
        }

        targetSlot.appendChild(app);
      }

      try {
        app.releasePointerCapture(pointerId);
      } catch (_) {}

      ghost.remove();
      app.classList.remove("drag-source");
      originSlot.classList.remove("drag-origin");
      document.body.classList.remove("dragging-active");

      dragState = null;
      dropCache = [];

      normalizeDock();
      updateDockVisual();
      suppressClickUntil = Date.now() + 450;
      saveLayout();
    }

    function handlePointerDown(event) {
      if (event.target.closest(".app-delete-button")) return;

      const app = event.target.closest(".app:not(.drag-ghost)");
      if (!app || event.button > 0) return;

      try {
        app.setPointerCapture(event.pointerId);
      } catch (_) {}

      if (isEditing()) {
        event.preventDefault();
        startDrag(app, event);
        return;
      }

      pressState = {
        app,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        latestX: event.clientX,
        latestY: event.clientY
      };

      longPressTimer = setTimeout(() => {
        if (!pressState || pressState.pointerId !== event.pointerId) return;

        const state = pressState;
        enterEditMode();

        startDrag(state.app, {
          pointerId: state.pointerId,
          clientX: state.latestX,
          clientY: state.latestY
        });

        clearLongPress();
      }, LONG_PRESS_MS);
    }

    function handlePointerMove(event) {
      if (dragState) {
        event.preventDefault();
        updateDrag(event);
        return;
      }

      if (!pressState || pressState.pointerId !== event.pointerId) return;

      pressState.latestX = event.clientX;
      pressState.latestY = event.clientY;

      const moved = Math.hypot(
        event.clientX - pressState.startX,
        event.clientY - pressState.startY
      );

      if (moved > 8) {
        clearLongPress();
      }
    }

    function handlePointerUp(event) {
      if (dragState && dragState.pointerId === event.pointerId) {
        event.preventDefault();
        finishDrag(event);
        return;
      }

      clearLongPress();
    }

    document.addEventListener("pointerdown", handlePointerDown, {
      passive: false
    });

    document.addEventListener("pointermove", handlePointerMove, {
      passive: false
    });

    document.addEventListener("pointerup", handlePointerUp, {
      passive: false
    });

    document.addEventListener("pointercancel", (event) => {
      if (dragState && dragState.pointerId === event.pointerId) {
        finishDrag(null, true);
      }

      clearLongPress();
    });


