      musicPlaylistCover.querySelector(":scope > span").textContent = playlist.cover;
      musicPlaylistCount.textContent = playlist.generated ? `${playlist.tracks.length} 首 · 听歌记录` : `${playlist.tracks.length} 首 · ${Math.max(18, playlist.tracks.length * 4)} 分钟`;
