    let cpMusicRun=0,cpMusicBusy=false,cpMusicQueue=[],cpMusicSource='',cpMusicAudio=null,cpMusicLyricIndex=-1;
    let cpMusicSongIdentity='',cpMusicMiniIdentity='',cpMusicPlaybackSourceKey='',cpMusicArtworkSourceKey='';
    const cpMusicCache=new Map();
