    async function openWechatApp() {
      openNativeApp(wechatAppScreen);
      void refreshPhoneRealWechatThread();
      const snapshot = phoneSnapshot();
      try { await refreshPhoneLoginRole(snapshot); if (phoneContentCurrent(snapshot)) syncWechatLoginState(); }
      catch (error) { if (phoneContentCurrent(snapshot)) showToast(error.message || '登录资料读取失败'); }
    }
    function updatePhoneLoginControls() {
      if (!phoneWechatModeButton) return;
      const phoneMode = phoneWechatMode === 'phone';
      wechatAccountInput.closest('label').querySelector('span').textContent = phoneMode ? '手机号' : '微信号';
      wechatAccountInput.placeholder = phoneMode ? '请输入角色的手机号' : '请输入角色的微信号';
      wechatAccountInput.type = phoneMode ? 'tel' : 'text';
      wechatAccountInput.setAttribute('autocomplete','off');
      wechatPasswordInput.closest('label').hidden = phoneMode;
      wechatPasswordInput.setAttribute('autocomplete','off');
      phoneWechatCodeInput.closest('.cp-wechat-code').hidden = !phoneMode;
      phoneWechatSmsLink.hidden = !phoneMode;
      phoneWechatModeButton.textContent = phoneMode ? '使用微信号和密码登录' : '使用手机号验证码登录';
      wechatLoginButton.disabled = phoneWechatBusy;
      phoneWechatModeButton.disabled = phoneWechatBusy;
      const remaining = Math.max(0, Math.ceil(((phoneContentState.data?.wechatAuth?.challenge?.resendAt || 0) - Date.now()) / 1000));
      phoneWechatSendCode.disabled = phoneWechatBusy || remaining > 0;
      phoneWechatSendCode.textContent = remaining ? remaining + '秒后重发' : '发送验证码';
      clearTimeout(phoneOtpTimer);
      if (remaining && phoneMode) phoneOtpTimer = setTimeout(updatePhoneLoginControls,1000);
    }
    function setPhoneLoginMode(mode) {
      phoneWechatMode = mode;
      wechatAccountInput.value = mode === 'phone' ? String(roleEntry.contact?.security?.phone || '') : '';
      wechatPasswordInput.value = ''; phoneWechatCodeInput.value = '';
      if (phoneWechatStatus) phoneWechatStatus.textContent='';
      updatePhoneLoginControls();
    }
    function phoneLoginSession(security,method) {
      return {account:String(security.account || '').trim(),phone:normalizePhoneNumber(security.phone),method,authenticatedAt:Date.now()};
    }
    async function performWechatLogin() {
      if (phoneWechatBusy) return;
      const snapshot = phoneSnapshot(), token = ++phoneWechatToken;
      const enteredAccount = wechatAccountInput.value.trim(), password = wechatPasswordInput.value, code = phoneWechatCodeInput.value.trim();
      const method = phoneWechatMode;
      if (!enteredAccount || !(method === 'phone' ? code : password)) { showToast(method === 'phone' ? '请输入手机号和验证码' : '请输入微信号和密码'); return; }
      phoneWechatBusy = true; updatePhoneLoginControls();
      try {
        const security = await refreshPhoneLoginRole(snapshot);
        let verificationError = '';
        const saved = await savePhoneContent(snapshot,{},undefined,previous => {
          const auth = previous?.wechatAuth || {};
          if (method === 'password') {
            if (!String(security.account || '').trim() || !security.password) throw new Error('请先在通讯录角色库填写微信号和密码');
            if (enteredAccount !== String(security.account).trim() || password !== String(security.password)) throw new Error('微信号或密码不正确');
          } else {
            if (!security.phone || normalizePhoneNumber(enteredAccount) !== normalizePhoneNumber(security.phone)) throw new Error('手机号与当前角色不匹配');
            const challenge = auth.challenge;
            if (!challenge || challenge.phone !== normalizePhoneNumber(security.phone) || Date.now() >= challenge.expiresAt) throw new Error('验证码不存在或已过期，请重新发送');
            if (challenge.attempts >= 5) throw new Error('验证码尝试次数过多，请重新发送');
            if (code !== challenge.code) {
              verificationError = '验证码不正确';
              return {wechatAuth:{...auth,challenge:{...challenge,attempts:challenge.attempts+1}}};
            }
          }
          return {wechatAuth:{session:phoneLoginSession(security,method),challenge:null}};
        });
        if (!phoneContentCurrent(snapshot)) return;
        phoneContentState.data = saved;
        if (verificationError) { showToast(verificationError); updatePhoneLoginControls(); return; }
        wechatPasswordInput.value = ''; phoneWechatCodeInput.value = '';
        syncWechatLoginState(); showToast('已登录' + roleEntry.contact.name + '的微信');
      } catch (error) { if (phoneContentCurrent(snapshot)) showToast(error.message || '登录失败，请重试'); }
      finally { if (token === phoneWechatToken) { phoneWechatBusy = false; updatePhoneLoginControls(); } }
    }
    async function sendPhoneWechatCode() {
      if (phoneWechatBusy) return;
      const snapshot = phoneSnapshot(), token = ++phoneWechatToken;
      const phone = normalizePhoneNumber(wechatAccountInput.value);
      if (!phone) { phoneWechatStatus.textContent='请先在通讯录角色库填写手机号，或输入角色的手机号'; return; }
      phoneWechatBusy = true; updatePhoneLoginControls();
      phoneWechatStatus.textContent='正在发送验证码…';
      try {
        const security = await refreshPhoneLoginRole(snapshot);
        if (!security.phone) throw new Error('请先在通讯录角色库填写手机号');
        if (phone !== normalizePhoneNumber(security.phone)) throw new Error('手机号与当前角色不匹配');
        const random = new Uint32Array(1);
        const cryptoProvider = globalThis.crypto || window.crypto;
        // This is local role-phone verification, including non-secure offline origins.
        if (cryptoProvider?.getRandomValues) cryptoProvider.getRandomValues(random);
        else random[0] = Math.floor(Math.random() * 1000000);
        const code = String(random[0] % 1000000).padStart(6,'0'), now = Date.now();
        const saved = await savePhoneContent(snapshot,{},undefined,previous => {
          const auth = previous?.wechatAuth || {};
          if (auth.challenge?.resendAt > now) throw new Error('请稍后再发送验证码');
          const message = {id:'wechat-code-' + now, sender:'微信',phone,createdAt:now,
            text:'【微信】登录验证码：' + code + '。5分钟内有效，请勿向他人泄露。'};
          return {wechatAuth:{...auth,challenge:{phone,code,expiresAt:now+300000,resendAt:now+60000,attempts:0}},
            sms:{items:[...(Array.isArray(previous?.sms?.items) ? previous.sms.items : []),message].slice(-30)}};
        });
        if (!phoneContentCurrent(snapshot)) return;
        phoneContentState.data = saved; renderPhoneWechatSms(); updatePhoneLoginControls();
        phoneWechatStatus.textContent='验证码已发送，可在上方通知或角色“信息”中查看';
        showPhoneSmsNotification('微信', saved.sms.items[saved.sms.items.length-1].text, code);
      } catch (error) { if (phoneContentCurrent(snapshot)) { phoneWechatStatus.textContent=error.message || '验证码发送失败，请重试'; showToast(phoneWechatStatus.textContent); } }
      finally { if (token === phoneWechatToken) { phoneWechatBusy = false; updatePhoneLoginControls(); } }
    }
    async function logoutWechat() {
      if (phoneWechatBusy) return;
      const snapshot = phoneSnapshot(), token = ++phoneWechatToken;
      phoneWechatBusy = true; updatePhoneLoginControls();
      try {
        const saved = await savePhoneContent(snapshot,{},undefined,() => ({wechatAuth:{session:null,challenge:null}}));
        if (!phoneContentCurrent(snapshot)) return;
        phoneContentState.data = saved; setPhoneLoginMode('password'); syncWechatLoginState();
      } catch (error) { if (phoneContentCurrent(snapshot)) showToast('退出登录失败，请重试'); }
      finally { if (token === phoneWechatToken) { phoneWechatBusy = false; updatePhoneLoginControls(); } }
    }
