    async function sendImessageMessage() {
      const value=imessageMessageInput.value.trim(), index=phoneSmsThreadIndex;
      if (!value || phoneSmsConversation || index === null || imessageSendButton.disabled) return;
      if (phoneContentState.jobs.has('sms')) { showToast('正在生成短信，请稍后再发送'); return; }
      const snapshot=phoneSnapshot(),threads=phoneContentState.data?.apps?.sms?.threads;
      if (!threads?.[index]) return;
      imessageSendButton.disabled=true;
      try {
        const updated=threads.map((thread,i)=>i===index ? {...thread,messages:[...thread.messages,{direction:'sent',text:value.slice(0,1800),date:new Date().toLocaleString()}]} : thread);
        const saved=await savePhoneContent(snapshot,{sms:{threads:updated}});
        if (!phoneContentCurrent(snapshot)) return;
        phoneContentState.data=saved;imessageMessageInput.value='';renderPhoneWechatSms();
        if (phoneSmsThreadIndex===index) openPhoneGeneratedSms(index);
      } catch(error) { if(phoneContentCurrent(snapshot)) showToast('短信保存失败，请重试'); }
      finally { if(phoneContentCurrent(snapshot)) imessageSendButton.disabled=phoneSmsConversation; }
    }

