    function renderGeneratedFiles(data) {
      closeFilesDetail(true);
      for(const [name,template] of phoneFilesTemplates){
        const panel=filesAppScreen.querySelector('[data-files-panel="'+name+'"]');
        const copy=template.cloneNode(true);panel.replaceChildren(...copy.childNodes);
        panel.querySelectorAll('[data-files-open]').forEach(button=>button.addEventListener('click',()=>openFilesDetail(button.dataset.filesOpen,button.dataset.filesKind||'folder')));
      }
      filesSearchInput.value='';
      if(!data?.items?.length){phoneEmpty(filesAppScreen.querySelector('[data-files-panel="browse"]'));return;}
      const panel = filesAppScreen.querySelector('[data-files-panel="browse"]');
      const section = makePhoneNode('div','files-section');
      const grid = makePhoneNode('div','files-folder-grid');
      section.append(makePhoneNode('h2','files-section-title','文件夹'),grid);
      section.dataset.phoneGeneratedFiles='true';panel.appendChild(section);
      const recent = filesAppScreen.querySelector('[data-files-panel="recents"]');
      const recentSection = makePhoneNode('div','files-section');
      const recentList = makePhoneNode('div','files-recents-list');
      recentSection.append(makePhoneNode('h2','files-section-title','角色文件'),recentList);
      recentSection.dataset.phoneGeneratedFiles='true';recent.appendChild(recentSection);
      const groups = new Map();
      for (const item of data?.items || []) {
        if (!groups.has(item.folder)) groups.set(item.folder, []);
        groups.get(item.folder).push(item);
        const row = makePhoneNode('button','files-file-row'); row.type='button';
        const icon = makePhoneNode('span','files-file-icon files-file-icon-svg');
        icon.innerHTML=filesIconMarkup(/\.pdf$/i.test(item.name) ? 'pdf' : /\.(jpg|jpeg|png|webp|svg)$/i.test(item.name) ? 'image' : 'text');
        const copy = makePhoneNode('div');
        copy.append(makePhoneNode('div','files-file-name',item.name),makePhoneNode('div','files-file-meta',item.folder));
        row.append(icon,copy,makePhoneNode('div','files-file-time',item.date));
        row.dataset.fileSearch=[item.folder,item.name,item.content].join(' ');
        row.addEventListener('click',()=>openPhoneGeneratedFile(item));
        recentList.appendChild(row);
      }
      if (!groups.size) { phoneEmpty(grid); phoneEmpty(recentList); return; }
      for (const [folder, items] of groups) {
        const card=makePhoneNode('button','files-folder-card'); card.type='button';
        const icon=makePhoneNode('div'); icon.innerHTML=filesIconMarkup('folder');
        const copy=makePhoneNode('div');
        copy.append(makePhoneNode('div','files-folder-name',folder),makePhoneNode('div','files-folder-meta',items.length+' 个项目'));
        card.append(icon,copy);
        card.dataset.fileSearch=[folder,...items.map(item=>item.name+' '+item.content)].join(' ');
        card.addEventListener('click',()=>openFilesDetail(folder,'folder',items));
        grid.appendChild(card);
      }
      filesSearchInput.value='';
    }
