      otherRoles: () => availablePhoneRoles.filter(item => String(item.id) !== String(roleEntry.contact?.id)).map(item => item.name),
      getData: () => phoneContentState.data?.apps?.forum,
      context: buildPhoneGenerationContext, readChat: phoneReadRealUserChat,
      config: resolvePhoneApi, request: (config, payload, options) => wcFetchChatCompletionJson({...config}, payload, options),
      prompt: () => getPhonePromptParts('forum').prompt,
