    if (existingHistoryIcon) historySettingsRow.querySelector('.settings-icon-box').replaceChildren(existingHistoryIcon.cloneNode(true));
    historySettingsRow.querySelector('.settings-icon-box').className='settings-icon-box settings-icon-time';
    historySettingsRow.setAttribute('aria-label','记录回溯：查看最近五次生成记录');
    settingsScreen.querySelector('[data-setting-item="储存空间"]').after(historySettingsRow);
    const insightsBody = key => insightsPages[key].querySelector('.cp-insights-scroll');
