    function historyAsReadableText(data) {
      const output=[];
      function visit(value,depth,label) {
        if(output.length>600)return;
        const indent='  '.repeat(Math.min(4,depth));
        if(Array.isArray(value)) {
          if(label)output.push(indent+label+'：');
          value.slice(0,40).forEach((item,i)=>visit(item,depth+1,'第 '+(i+1)+' 条'));
          return;
        }
        if(value&&typeof value==='object'){
          if(label)output.push(indent+label);
          for(const [key,val] of Object.entries(value)){
            if(key==='generatedAt')continue;
            visit(val,depth+1,insightKeyLabels[key]||key);
          }
          return;
        }
        output.push(indent+(label?label+'：':'')+String(value??''));
      }
      visit(data,0,'');
      return output.join('\n').slice(0,36000)||'该记录暂时没有可查看的内容。';
    }
